INSERT INTO catalog_modules (id, course_id, title, summary, `position`) VALUES
  ('d0000001-0000-4000-8000-000000000048', 'c0000001-0000-4000-8000-000000000014',
   'Level 1 - Basic',
   'What the thing in the middle is. A language model predicts the next token and nothing else; this level builds that picture carefully, because every later decision - why examples help, why the context window is the real constraint, why a confident citation can be fiction - is a consequence of it. It ends with a plain account of what these models do well and where they fail, which is the most useful thing to know before you build anything.', 1),
  ('d0000001-0000-4000-8000-000000000049', 'c0000001-0000-4000-8000-000000000014',
   'Level 2 - Intermediate',
   'Directing the model. A prompt is not a request, it is a specification - and this level treats it like one: stating the task, the format, the constraints and the escape hatch, then getting output structured enough to parse, then letting the model call your functions. It closes on the idea that ties the level together: the context window is the real program, and assembling it is the work.', 2),
  ('d0000001-0000-4000-8000-00000000004a', 'c0000001-0000-4000-8000-000000000014',
   'Level 3 - Advanced',
   'Grounding and proof. First embeddings, which turn meaning into coordinates so that text can be searched by what it is about rather than which words it contains. Then retrieval-augmented generation end to end, which is how a model answers from your documents. Then the part that most teams skip and then regret: evaluating a system whose output has no single right answer.', 3),
  ('d0000001-0000-4000-8000-00000000004b', 'c0000001-0000-4000-8000-000000000014',
   'Level 4 - Expert',
   'Putting it in production. Choosing between prompting, retrieval and fine-tuning with reasons rather than fashion; the arithmetic of cost, latency and caching that decides whether the thing is viable at scale; and prompt injection, which is the security problem this architecture creates and which no amount of prompt wording fixes. It ends with the Expert Exam over the whole course.', 4)
ON DUPLICATE KEY UPDATE title = VALUES(title), summary = VALUES(summary);

