INSERT INTO content_lesson_diagrams (lesson_id, title, alt, caption, spec, `position`) VALUES
  ('e0000001-0000-4000-8000-000000000111',
   'How a question becomes a grounded answer',
   'A user question first goes to retrieval, which searches your own documents for the passages most related to it. Those passages are assembled with the question and your instructions into a single prompt. The model reads that prompt and predicts an answer one token at a time. The answer is returned with the sources it was built from, so a reader can check it. The model itself holds no copy of your documents; everything it knows about them arrived in the prompt.',
   'The model is one box in the middle. Most of the engineering in generative AI is the boxes either side of it.',
   '{"nodes": [{"label": "Question", "note": "What the user actually asked"}, {"label": "Retrieval", "note": "The passages from your documents that relate to it"}, {"label": "Prompt", "note": "Instructions, passages and question, assembled into one context"}, {"label": "Model", "note": "Predicts the answer token by token from that context"}, {"label": "Answer with sources", "note": "Returned with the passages it was built from, so it can be checked"}], "edges": [{"label": "searched against"}, {"label": "assembled into"}, {"label": "read by"}, {"label": "returned as"}]}', 1)
